-- Add the remaining standalone rules explicitly printed in the volume 3 pages and contents.
begin;

with extra (lesson_number, sort_order, title, summary, explanation, examples, irab) as (
  values
  ('2', 133, 'وَاوُ الْعَطْفِ (Ва соединительная)',
   'Союз و связывает однородные члены или предложения.',
   'وَاوُ الْعَطْفِ присоединяет второй элемент к первому без изменения его исходной синтаксической роли. После неё слово получает тот же падеж, что и предшествующий однородный член: مَرْفُوع с مَرْفُوع, مَنْصُوب с مَنْصُوب и مَجْرُور с مَجْرُور. Смысл союза — совместное упоминание, а не причинность или последовательность.',
   '<li><span dir="rtl" lang="ar">جَاءَ مُحَمَّدٌ وَعَلِيٌّ</span> — пришли Мухаммад и Али.</li><li><span dir="rtl" lang="ar">قَرَأْتُ الْكِتَابَ وَالدَّفْتَرَ</span> — я прочитал книгу и тетрадь.</li><li><span dir="rtl" lang="ar">مَرَرْتُ بِالْمَدْرَسَةِ وَالْمَسْجِدِ</span> — я прошёл мимо школы и мечети.</li>',
   '<span dir="rtl" lang="ar">عَلِيٌّ: مَعْطُوفٌ عَلَى مُحَمَّدٌ مَرْفُوعٌ بِالضَّمَّةِ.</span><br><span dir="rtl" lang="ar">الدَّفْتَرَ: مَعْطُوفٌ عَلَى الْكِتَابَ مَنْصُوبٌ بِالْفَتْحَةِ.</span><br><span dir="rtl" lang="ar">الْمَسْجِدِ: مَعْطُوفٌ عَلَى الْمَدْرَسَةِ مَجْرُورٌ بِالْكَسْرَةِ.</span>'),
  ('2', 134, 'وَاوُ الْقَسَمِ (Ва клятвенная)',
   'Предлог و используется для выражения клятвы.',
   'Вَاوُ الْقَسَمِ — это حرف جرّ. Она входит в состав оборота клятвы и делает следующее имя مَجْرُور: وَاللَّهِ، وَالْفَجْرِ. Ответ клятвы может быть предложением и часто усиливается لام или قد. Не следует смешивать واو القسم с واو العطف: их синтаксические функции различны.',
   '<li><span dir="rtl" lang="ar">وَاللَّهِ لَأَجْتَهِدَنَّ</span> — клянусь Аллахом, я непременно буду усердствовать.</li><li><span dir="rtl" lang="ar">وَالْفَجْرِ إِنَّ الْحَقَّ وَاضِحٌ</span> — клянусь рассветом, истина ясна.</li><li><span dir="rtl" lang="ar">وَرَبِّي مَا كَذَبْتُ</span> — клянусь моим Господом, я не лгал.</li>',
   '<span dir="rtl" lang="ar">اللَّهِ: اسْمٌ مَجْرُورٌ بِوَاوِ الْقَسَمِ، وَالْجَارُّ وَالْمَجْرُورُ مُتَعَلِّقٌ بِفِعْلِ الْقَسَمِ الْمَحْذُوفِ.</span><br><span dir="rtl" lang="ar">الْفَجْرِ: اسْمٌ مَجْرُورٌ بِوَاوِ الْقَسَمِ.</span><br><span dir="rtl" lang="ar">رَبِّي: اسْمٌ مَجْرُورٌ بِوَاوِ الْقَسَمِ، وَالْيَاءُ مَضَافٌ إِلَيْهِ.</span>'),
  ('15', 135, 'هَاءُ (اسم فعل بمعنى خُذْ) (Имя-глагол «возьми»)',
   'Форма هَاءَ، هَاءِي، هَاؤُمُ употребляется как اسم فعل для побуждения взять.',
   'هَاءُ اسم فعل أمر بمعنى خُذْ. Она не является обычным глаголом и не принимает обычные глагольные окончания. Форма меняется по адресату: هَاءَ للمفرد المذكر، هَاءِي للمفرد المؤنث، هَاؤُمُ للجمع. В предложении она обозначает приказ, а последующее слово обычно является مفعولاً به.',
   '<li><span dir="rtl" lang="ar">هَاءَ الْكِتَابَ يَا عَلِيُّ</span> — возьми книгу, Али.</li><li><span dir="rtl" lang="ar">هَاءِي الْقَلَمَ يَا آمِنَةُ</span> — возьми ручку, Амина.</li><li><span dir="rtl" lang="ar">هَاؤُمُ الْكُتُبَ يَا إِخْوَةُ</span> — возьмите книги, братья.</li>',
   '<span dir="rtl" lang="ar">هَاءَ: اسْمُ فِعْلِ أَمْرٍ بِمَعْنَى خُذْ، وَالْكِتَابَ مَفْعُولٌ بِهِ مَنْصُوبٌ.</span><br><span dir="rtl" lang="ar">هَاءِي: اسْمُ فِعْلِ أَمْرٍ بِمَعْنَى خُذِي، وَالْقَلَمَ مَفْعُولٌ بِهِ.</span><br><span dir="rtl" lang="ar">هَاؤُمُ: اسْمُ فِعْلِ أَمْرٍ لِلْجَمْعِ بِمَعْنَى خُذُوا، وَالْكُتُبَ مَفْعُولٌ بِهِ.</span>')
)
insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
select 'Мединский курс (Том 3)', lesson_number, title,
  '<p><strong>Академическое объяснение.</strong> ' || explanation || '</p><p><strong>Три примера.</strong></p><ol>' || examples || '</ol><p><strong>Полный разбор إعراب.</strong><br>' || irab || '</p>',
  sort_order, 'rule', summary
from extra
where not exists (
  select 1 from public.rules r
  where r.course_name = 'Мединский курс (Том 3)' and r.title = extra.title
);

commit;
